/**
 * Trail of links from the root to the current page (`design/components/breadcrumbs.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/breadcrumbs.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { Component, DestroyRef, ViewEncapsulation, inject, input, output } from '@angular/core'

import {
  Icon,
  MEMBER_PROVIDERS,
  Ref,
  agentMember,
  agentPress,
  derived,
  elementRef,
  mountEffect,
  useMember,
  type Each,
} from '@polymorph/angular'
import styles from '@polymorph/recipes/structure/breadcrumbs.module.css'
import { Button, type ButtonProps } from '../controls/Button'
import { Menu, type MenuProps } from '../overlays/Menu'

export interface BreadcrumbItem {
  label: string
  href?: string
  onSelect?: () => void
}

/** Trail of links from the root to the current page: the inputs it takes, by the React member's prop names. */
export interface BreadcrumbsProps {
  /**
   * Opens the overflow on mount, for galleries and tests only.
   */
  defaultOpen?: boolean
  /**
   * The last item is the current page; its `href`/`onSelect` are ignored.
   */
  items: BreadcrumbItem[]
  /**
   * The landmark's accessible name, default `Breadcrumb`; localized hosts pass their own.
   */
  label?: string
  /**
   * Above this count, shows the first crumb, overflow and last two; `Infinity` disables it.
   */
  maxItems?: number
  /**
   * The overflow control's accessible name, default `Show path`.
   */
  overflowLabel?: string
}

/** Trail of links from the root to the current page. */
@Component({
  selector: 'pm-breadcrumbs',
  encapsulation: ViewEncapsulation.None,
  host: { style: 'display: contents' },
  providers: [...MEMBER_PROVIDERS],
  imports: [Ref, Button, Icon, Menu],
  // prettier-ignore
  template: `<nav
[attr.class]="e1()"
[attr.aria-label]="e2()"
data-member="breadcrumbs"
[pmRef]="root"
><!-- list -->
<ol
[attr.class]="e3()"
>@for (rung of e4(); track e5(rung, $index); let at = $index) {<!-- item -->
<li
[attr.class]="e6()"
>@if (e7(rung)) {<pm-menu
[defaultOpen]="e8(rung)"
[items]="e9(rung)"
><ng-container ngProjectAs="[slot=trigger]"><pm-button
variant="ghost"
tone="neutral"
size="sm"
[iconOnly]="e10(rung)"
icon="overflow"
[label]="e11(rung)"
></pm-button></ng-container></pm-menu>} @else if (e12(rung, at)) {<span
[attr.class]="e13(rung, at)"
aria-current="page"
>{{ e14(rung, at) }}</span>} @else if (e15(rung, at)) {<a
[attr.class]="e16(rung, at)"
[attr.href]="e17(rung, at)"
(click)="h1($event, rung, at)"
>{{ e18(rung, at) }}</a>} @else if (e19(rung, at)) {<button
[attr.class]="e20(rung, at)"
type="button"
(click)="h2(rung, at)"
>{{ e21(rung, at) }}</button>} @else {<span
[attr.class]="e22(rung, at)"
>{{ e23(rung, at) }}</span>}
@if (e24(at)) {<!-- separator -->
<span
[attr.class]="e25(at)"
><pm-icon
name="next"
size="sm"
></pm-icon></span>}</li>}</ol></nav>`,
})
export class Breadcrumbs {
  /**
   * Opens the overflow on mount, for galleries and tests only.
   */
  readonly defaultOpen = input<BreadcrumbsProps['defaultOpen']>(undefined)
  /**
   * The last item is the current page; its `href`/`onSelect` are ignored.
   */
  readonly items = input.required<BreadcrumbsProps['items']>()
  /**
   * The landmark's accessible name, default `Breadcrumb`; localized hosts pass their own.
   */
  readonly label = input<Exclude<BreadcrumbsProps['label'], undefined>, BreadcrumbsProps['label']>(
    'Breadcrumb',
    {
      transform: (value: BreadcrumbsProps['label']) => (value === undefined ? 'Breadcrumb' : value),
    },
  )
  /**
   * Above this count, shows the first crumb, overflow and last two; `Infinity` disables it.
   */
  readonly maxItems = input<
    Exclude<BreadcrumbsProps['maxItems'], undefined>,
    BreadcrumbsProps['maxItems']
  >(4, { transform: (value: BreadcrumbsProps['maxItems']) => (value === undefined ? 4 : value) })
  /**
   * The overflow control's accessible name, default `Show path`.
   */
  readonly overflowLabel = input<
    Exclude<BreadcrumbsProps['overflowLabel'], undefined>,
    BreadcrumbsProps['overflowLabel']
  >('Show path', {
    transform: (value: BreadcrumbsProps['overflowLabel']) =>
      value === undefined ? 'Show path' : value,
  })
  /**
   * The app's router, for every crumb with an `href` (`link.md` §Routing): a click that would
   * navigate this tab, and a crumb chosen from the overflow, call it in place of the browser.
   */
  readonly onNavigate = output<string>({ alias: 'navigate' })
  protected readonly $ = useMember({
    events: ['navigate'],
    props: {
      defaultOpen: () => this.defaultOpen(),
      items: () => this.items(),
      label: () => this.label(),
      maxItems: () => this.maxItems(),
      overflowLabel: () => this.overflowLabel(),
    },
  })
  protected readonly $p = this.$.props
  protected readonly root = elementRef<HTMLElement>()
  protected readonly collapsed = derived(() => this.$p.items.length > this.$p.maxItems)
  protected readonly row = derived(() =>
    this.collapsed.value
      ? [...this.$p.items.slice(0, 1), null, ...this.$p.items.slice(1).slice(-2)]
      : this.$p.items,
  )
  protected readonly last = derived(() => this.row.value.length - 1)
  protected readonly hidden = derived(() =>
    this.collapsed.value
      ? this.$p.items.slice(1, -2).map((item) => ({
          label: item.label,
          onSelect: () => {
            if (item.onSelect) item.onSelect()
            else if (item.href !== undefined) {
              if (this.$.listening(this.onNavigate, 'onNavigate'))
                this.$.emit(this.onNavigate, 'onNavigate', item.href)
              else window.location.assign(item.href)
            }
          },
        }))
      : [],
  )
  protected readonly navigatesHere = derived(
    () =>
      (event: MouseEvent): boolean =>
        !event.defaultPrevented &&
        event.button === 0 &&
        !event.metaKey &&
        !event.ctrlKey &&
        !event.shiftKey &&
        !event.altKey,
  )
  protected readonly route = derived(() => (event: MouseEvent, href: string | undefined): void => {
    if (
      href === undefined ||
      !this.$.listening(this.onNavigate, 'onNavigate') ||
      !this.navigatesHere.value(event)
    )
      return
    event.preventDefault()
    this.$.emit(this.onNavigate, 'onNavigate', href)
  })
  private release1: (() => void) | undefined

  constructor() {
    inject(DestroyRef).onDestroy(() => this.release1?.())
    mountEffect(() => this.effect1())
  }

  protected e1() {
    return styles.nav
  }

  protected e2() {
    return this.$p.label
  }

  protected e3() {
    return styles.list
  }

  e4() {
    return this.row.value
  }

  protected e5(rung: Each<ReturnType<Breadcrumbs['e4']>>, at: number) {
    return rung === null ? 'overflow' : `${at}-${rung.label}`
  }

  protected e6() {
    return styles.item
  }

  protected e7(rung: Each<ReturnType<Breadcrumbs['e4']>>) {
    return rung === null
  }

  protected e8(rung: Each<ReturnType<Breadcrumbs['e4']>>): MenuProps['defaultOpen'] {
    if (!(rung === null)) return undefined as never
    return this.$p.defaultOpen
  }

  protected e9(rung: Each<ReturnType<Breadcrumbs['e4']>>): MenuProps['items'] {
    if (!(rung === null)) return undefined as never
    return this.hidden.value
  }

  protected e10(rung: Each<ReturnType<Breadcrumbs['e4']>>): ButtonProps['iconOnly'] {
    if (!(rung === null)) return undefined as never
    return true
  }

  protected e11(rung: Each<ReturnType<Breadcrumbs['e4']>>): ButtonProps['label'] {
    if (!(rung === null)) return undefined as never
    return this.$p.overflowLabel
  }

  protected e12(rung: Each<ReturnType<Breadcrumbs['e4']>>, at: number) {
    if (rung === null) return undefined as never
    return at === this.last.value
  }

  protected e13(rung: Each<ReturnType<Breadcrumbs['e4']>>, at: number) {
    if (rung === null) return undefined as never
    if (!(at === this.last.value)) return undefined as never
    return styles.crumb
  }

  protected e14(rung: Each<ReturnType<Breadcrumbs['e4']>>, at: number) {
    if (rung === null) return undefined as never
    if (!(at === this.last.value)) return undefined as never
    return rung.label
  }

  protected e15(rung: Each<ReturnType<Breadcrumbs['e4']>>, at: number) {
    if (rung === null) return undefined as never
    if (at === this.last.value) return undefined as never
    return rung.href !== undefined
  }

  protected e16(rung: Each<ReturnType<Breadcrumbs['e4']>>, at: number) {
    if (rung === null) return undefined as never
    if (at === this.last.value) return undefined as never
    if (!(rung.href !== undefined)) return undefined as never
    return styles.crumb
  }

  protected e17(rung: Each<ReturnType<Breadcrumbs['e4']>>, at: number) {
    if (rung === null) return undefined as never
    if (at === this.last.value) return undefined as never
    if (!(rung.href !== undefined)) return undefined as never
    return rung.href
  }

  protected h1($event: MouseEvent, rung: Each<ReturnType<Breadcrumbs['e4']>>, at: number): void {
    if (rung === null) return
    if (at === this.last.value) return
    if (!(rung.href !== undefined)) return
    void (rung.onSelect?.(), this.route.value($event, rung.href))
  }

  protected e18(rung: Each<ReturnType<Breadcrumbs['e4']>>, at: number) {
    if (rung === null) return undefined as never
    if (at === this.last.value) return undefined as never
    if (!(rung.href !== undefined)) return undefined as never
    return rung.label
  }

  protected e19(rung: Each<ReturnType<Breadcrumbs['e4']>>, at: number) {
    if (rung === null) return undefined as never
    if (at === this.last.value) return undefined as never
    if (rung.href !== undefined) return undefined as never
    return rung.onSelect !== undefined
  }

  protected e20(rung: Each<ReturnType<Breadcrumbs['e4']>>, at: number) {
    if (rung === null) return undefined as never
    if (at === this.last.value) return undefined as never
    if (rung.href !== undefined) return undefined as never
    if (!(rung.onSelect !== undefined)) return undefined as never
    return styles.crumb
  }

  protected h2(rung: Each<ReturnType<Breadcrumbs['e4']>>, at: number): void {
    if (rung === null) return
    if (at === this.last.value) return
    if (rung.href !== undefined) return
    if (!(rung.onSelect !== undefined)) return
    rung.onSelect?.()
  }

  protected e21(rung: Each<ReturnType<Breadcrumbs['e4']>>, at: number) {
    if (rung === null) return undefined as never
    if (at === this.last.value) return undefined as never
    if (rung.href !== undefined) return undefined as never
    if (!(rung.onSelect !== undefined)) return undefined as never
    return rung.label
  }

  protected e22(rung: Each<ReturnType<Breadcrumbs['e4']>>, at: number) {
    if (rung === null) return undefined as never
    if (at === this.last.value) return undefined as never
    if (rung.href !== undefined) return undefined as never
    if (rung.onSelect !== undefined) return undefined as never
    return styles.crumb
  }

  protected e23(rung: Each<ReturnType<Breadcrumbs['e4']>>, at: number) {
    if (rung === null) return undefined as never
    if (at === this.last.value) return undefined as never
    if (rung.href !== undefined) return undefined as never
    if (rung.onSelect !== undefined) return undefined as never
    return rung.label
  }

  protected e24(at: number) {
    return at !== this.last.value
  }

  protected e25(at: number) {
    if (!(at !== this.last.value)) return undefined as never
    return styles.separator
  }

  private effect1(): void {
    this.release1?.()
    const ran = agentMember({
      member: 'Breadcrumbs',
      element: () => this.root.value,
      state: () => ({
        items: this.$p.items
          .filter(
            (item, at) => this.$p.items.findIndex((other) => other.label === item.label) === at,
          )
          .map((item) => ({
            id: item.label,
            label: item.label,
            ...(item === this.$p.items[this.$p.items.length - 1] ||
            (item.href === undefined && item.onSelect === undefined)
              ? { disabled: true }
              : {}),
          })),
      }),
      actions: {
        choose: {
          argument: 'id',
          run: (value) =>
            (() => {
              const item = this.$p.items.find((candidate) => candidate.label === value)
              if (item === undefined) return
              const shown = this.row.value.indexOf(item)
              if (shown === -1) this.hidden.value.find((entry) => entry.label === value)?.onSelect()
              else
                agentPress(
                  this.root.value
                    ?.querySelectorAll(':scope > ol > li')
                    [shown]?.querySelector('a, button'),
                )
            })(),
        },
      },
      withholds: () =>
        this.hidden.value.length === 0
          ? null
          : this.root.value?.querySelectorAll(':scope > ol > li')[1],
    })
    this.release1 = () => {
      ran()
    }
  }
}
